"""Kiểm thử tự động khối nền chung. Chạy: node serve.cjs, rồi python kiem_thu_nen_chung.py"""
import asyncio,os
from playwright.async_api import async_playwright
H=os.path.dirname(os.path.abspath(__file__));U='http://127.0.0.1:4173/';R=[]
def ok(n,c,i=''):R.append(c);print(('ĐẠT  ' if c else 'HỎNG ')+n+(' · '+str(i) if i and not c else ''))
async def ready(pg):await pg.wait_for_function('window.AP_READY===true',timeout=15000);await pg.wait_for_timeout(300)
async def main():
  async with async_playwright() as p:
    b=await p.chromium.launch(args=['--use-fake-device-for-media-stream','--use-fake-ui-for-media-stream'])
    ctx=await b.new_context(viewport={'width':390,'height':844},service_workers='allow',accept_downloads=True)
    await ctx.grant_permissions(['geolocation','camera'],origin=U.rstrip('/'));await ctx.set_geolocation({'latitude':8.62,'longitude':104.72})
    pg=await ctx.new_page();errs=[];pg.on('pageerror',lambda e:errs.append(str(e)[:200]));pg.on('console',lambda m:m.type=='error' and errs.append(m.text[:200]))
    await pg.goto(U);await ready(pg)
    ok('1. Khởi động không lỗi, mở màn Tạo dự án',not errs and 'Tạo dự án' in await pg.inner_text('#view'),errs)
    await pg.fill('#pjName','Đường ra đảo Hòn Khoai');await pg.fill('#pjPlace','Đất Mũi, Cà Mau');await pg.fill('#pjRep','Kỹ sư thử');await pg.click('#pjOk');await pg.wait_for_timeout(600)
    t=await pg.inner_text('#view');ok('2. Tạo dự án, về trang Việc hôm nay','Việc hôm nay' in t and 'Hòn Khoai' in t and 'Đất Mũi' in t,t[:200])
    await pg.click('#nav a[href="#photos"]');await pg.wait_for_timeout(300);await pg.set_input_files('#pFile',[H+'/anh1.jpg',H+'/anh2.jpg']);await pg.wait_for_function("document.querySelectorAll('.ph').length===2",timeout=20000)
    ok('3. Nhập 2 ảnh từ máy vào Kho ảnh',True)
    await pg.click('#nav a.shot');await pg.wait_for_function("document.querySelector('#cv')&&document.querySelector('#cv').videoWidth>0",timeout=15000);await pg.click('#cShot');await pg.wait_for_function("document.querySelector('#cN').textContent==='1 ảnh'",timeout=15000)
    info=await pg.inner_text('#cinfo');await pg.click('.cam-x');await pg.wait_for_function("document.querySelectorAll('.ph').length===3",timeout=10000)
    ok('4. Chụp bằng camera trong app, ảnh vào kho',True);ok('5. Camera hiện ngày giờ, địa danh, GPS','Đất Mũi' in info and '8.62' in info,info)
    await pg.locator('.ph').first.click();await pg.wait_for_selector('#pdCap');d=await pg.inner_text('.sheet')
    ok('6. Chi tiết ảnh có GPS, người chụp, mã kiểm tra','8.62' in d and 'Kỹ sư thử' in d and 'Mã kiểm tra' in d,d[:300])
    await pg.fill('#pdCap','Ống vách sau khi hạ');await pg.click('#pdSave');await pg.wait_for_timeout(500)
    await pg.reload();await ready(pg);await pg.click('#nav a[href="#photos"]');await pg.wait_for_function("document.querySelectorAll('.ph').length===3",timeout=10000)
    ok('7. Tải lại trang: dự án và 3 ảnh còn nguyên','Hòn Khoai' in await pg.inner_text('#view'))
    ok('8. Không dùng localStorage',await pg.evaluate('localStorage.length')==0)
    await pg.click('#nav a[href="#project"]');await pg.wait_for_selector('#bkOut')
    async with pg.expect_download(timeout=30000) as dl: await pg.click('#bkOut')
    f=H+'/_saoluu.zip';await (await dl.value).save_as(f);ok('9. Sao lưu ra gói .zip',os.path.getsize(f)>20000,os.path.getsize(f))
    await pg.wait_for_selector('#wipe');await pg.click('#wipe');await pg.fill('#cfTyped','XOA');await pg.click('#cfOk');await pg.wait_for_timeout(1200);await ready(pg)
    ok('10. Xóa toàn bộ dữ liệu, về màn Tạo dự án','Tạo dự án' in await pg.inner_text('#view'))
    await pg.set_input_files('#bkFile',f);await pg.wait_for_function("document.querySelector('#view').innerText.includes('Việc hôm nay')",timeout=20000)
    await pg.click('#nav a[href="#photos"]');await pg.wait_for_function("document.querySelectorAll('.ph').length===3",timeout=10000)
    await pg.locator('.ph').first.click();await pg.wait_for_selector('#pdCap');ok('11. Khôi phục từ gói: đủ 3 ảnh và ghi chú',await pg.input_value('#pdCap')=='Ống vách sau khi hạ')
    await pg.click('#cfNo') if await pg.locator('#cfNo').count() else await pg.mouse.click(10,10)
    await pg.evaluate('navigator.serviceWorker.ready');await pg.wait_for_timeout(1500);await ctx.set_offline(True);n=len(errs)
    await pg.reload();await ready(pg);await pg.click('#nav a[href="#today"]');await pg.wait_for_timeout(400);ok('12. Mất mạng vẫn mở được ứng dụng','Việc hôm nay' in await pg.inner_text('#view') and len(errs)==n,errs[n:])
    await ctx.set_offline(False);ok('13. Không phát sinh lỗi trong suốt quá trình',not errs,errs)
    for h,nm in [('#today','1_homnay'),('#records','2_hoso'),('#photos','3_khoanh'),('#project','4_duan'),('#camera','5_camera')]:
        await pg.goto(U+h);await pg.wait_for_timeout(900);await pg.screenshot(path=f'{H}/man_{nm}.png')
    os.remove(f);await b.close()
  print(f'KẾT QUẢ: {sum(R)}/{len(R)} đạt')
asyncio.run(main())
